// AGENTS.md invariant 10: migrations are generated by drizzle-kit and never edited after being
// applied, and the generated schema files stay current. Without a database or secrets, checks:
//   1. With a base ref: no migration SQL or snapshot that exists at the base is modified, deleted
//      or renamed, and the journal only gains entries, each with a `when` above every earlier one.
//      Drizzle's migrator applies a migration only if its `when` is newer than the last applied
//      one, so an edited (or out-of-order) migration is silently skipped on existing databases
//      while fresh ones (CI, previews) apply it: production and fresh databases diverge.
//   2. `drizzle-kit check`: no two migrations share a parent snapshot (parallel branches).
//   3. `drizzle-kit generate` writes nothing: no schema change is missing its migration.
//   4. `pnpm auth:generate` leaves packages/db/src/schema/auth.ts unchanged (Better Auth bumps).
// The base is compared with the working tree. A missing base commit is an error, never a pass; an
// all-zero base (a newly created branch) skips check 1. scripts/check-schema-sql.sh checks that
// the migrations' SQL builds the schema (needs Postgres). Run by ci.yml and `pnpm db:check`.
// Usage: node scripts/check-migrations.mjs [<base-ref> | --default-base] [--history-only]
// --default-base (`pnpm db:check`): $BASE if set (never empty or all zeros), else origin/main, else
// the merge base with upstream/main (a product not pushed yet, docs/runbooks/start-new-product.md),
// but only while every migration here already exists there: git can't tell whether a migration
// added after it was applied somewhere. Otherwise it fails and asks for BASE; it never skips check 1.
import { execFileSync, spawnSync } from 'node:child_process'
import { existsSync, lstatSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

const args = process.argv.slice(2)
const historyOnly = args.includes('--history-only')

const git = (...a) => execFileSync('git', a, { encoding: 'utf8' })
const root = git('rev-parse', '--show-toplevel').trim()
const DIR = 'packages/db/drizzle'
const JOURNAL = `${DIR}/meta/_journal.json`
const AUTH_SCHEMA = 'packages/db/src/schema/auth.ts'
const errors = []

const isCommit = (ref) =>
  spawnSync('git', ['cat-file', '-e', `${ref}^{commit}`], { cwd: root }).status === 0

function noBase(why) {
  console.error(
    `check-migrations: no base: ${why}; set BASE=<commit> (the last commit whose migrations may have been applied anywhere)`,
  )
  process.exit(1)
}

const journalTags = (text) => JSON.parse(text).entries.map((e) => e.tag)

function defaultBase() {
  if (process.env.BASE !== undefined) {
    if (process.env.BASE === '' || /^0+$/.test(process.env.BASE))
      noBase(`BASE is ${process.env.BASE ? 'all zeros' : 'empty'}`)
    return process.env.BASE
  }
  if (isCommit('origin/main')) return 'origin/main'
  if (!isCommit('upstream/main')) noBase('neither origin/main nor upstream/main is here')
  const r = spawnSync('git', ['merge-base', 'HEAD', 'upstream/main'], {
    cwd: root,
    encoding: 'utf8',
  })
  if (r.status !== 0) noBase('HEAD shares no history with upstream/main')
  const mergeBase = r.stdout.trim()
  const atBase = spawnSync('git', ['show', `${mergeBase}:${JOURNAL}`], {
    cwd: root,
    encoding: 'utf8',
  })
  const known = new Set(atBase.status === 0 ? journalTags(atBase.stdout) : [])
  const added = journalTags(readFileSync(join(root, JOURNAL), 'utf8')).filter((t) => !known.has(t))
  if (added.length)
    noBase(
      `no origin/main, and ${added.join(', ')} postdate the merge base with upstream/main, so it can't tell whether they were applied`,
    )
  console.log(
    `check-migrations: no origin/main; base is the merge base with upstream/main (${mergeBase})`,
  )
  return mergeBase
}

const base = args.includes('--default-base') ? defaultBase() : args.find((a) => !a.startsWith('--'))

function checkHistory(base) {
  if (/^0+$/.test(base)) {
    console.log(`check-migrations: base ${base} is all zeros (new branch); history not checked`)
    return
  }
  if (!isCommit(base)) {
    errors.push(`base ${base} is not a commit in this checkout (fetch it first)`)
    return
  }
  const changes = git('-C', root, 'diff', '--name-status', '-M', base, '--', DIR)
  for (const line of changes.split('\n').filter(Boolean)) {
    const [status, path, renamed] = line.split('\t')
    if (status === 'A' || (status === 'M' && path === JOURNAL)) continue
    const what =
      {
        M: 'modified',
        D: 'deleted',
        R: `renamed to ${renamed}`,
        T: 'changed type (e.g. to a symlink)',
      }[status[0]] ?? status
    errors.push(`${path} exists on ${base} and was ${what}: add a new migration instead`)
  }
  checkJournal(base)
}

function checkJournal(base) {
  const before = git('-C', root, 'ls-tree', base, '--', JOURNAL)
    ? JSON.parse(git('-C', root, 'show', `${base}:${JOURNAL}`))
    : { entries: [] }
  const path = join(root, JOURNAL)
  if (!existsSync(path)) return // deleted: reported as a change above
  const after = JSON.parse(readFileSync(path, 'utf8'))
  const header = (j) => JSON.stringify({ ...j, entries: undefined })
  if (before.version && header(before) !== header(after))
    errors.push(`${JOURNAL}: its header changed`)
  before.entries.forEach((entry, i) => {
    if (JSON.stringify(entry) !== JSON.stringify(after.entries[i]))
      errors.push(`${JOURNAL}: entry ${i} (${entry.tag}) changed or was removed`)
  })
  after.entries.forEach((entry, i) => {
    // The migrator reads `<tag>.sql` next to the journal and compares `when` as a number: a path in
    // the tag or a symlink would put an applied migration's SQL outside this check, and a string
    // `when` would order differently here than there.
    if (!/^[A-Za-z0-9_-]+$/.test(entry.tag ?? ''))
      errors.push(
        `${JOURNAL}: entry ${i} has tag ${JSON.stringify(entry.tag)}, not a plain file name`,
      )
    else if (!lstatSync(join(root, DIR, `${entry.tag}.sql`), { throwIfNoEntry: false })?.isFile())
      errors.push(
        `${JOURNAL}: entry ${i}: ${DIR}/${entry.tag}.sql is missing or not a regular file`,
      )
    if (!Number.isSafeInteger(entry.when))
      errors.push(
        `${JOURNAL}: entry ${i} (${entry.tag}) has \`when\` ${JSON.stringify(entry.when)}, not an integer`,
      )
    else if (i > 0 && !(entry.when > after.entries[i - 1].when))
      errors.push(
        `${JOURNAL}: entry ${i} (${entry.tag}) has \`when\` ${entry.when}, not after ${after.entries[i - 1].when}; the migrator would skip it on existing databases (regenerate it)`,
      )
  })
}

// Runs a step; returns false (and records why) if it fails or waits for input.
function run(label, cmd, cmdArgs) {
  const r = spawnSync(cmd, cmdArgs, {
    cwd: root,
    stdio: ['ignore', 'inherit', 'inherit'],
    timeout: 120_000,
  })
  if (r.status === 0) return true
  errors.push(
    `${label} failed${r.error ? ` (${r.error.code}; it may be waiting for input: run it locally)` : ''}`,
  )
  return false
}

const porcelain = () => git('-C', root, 'status', '--porcelain', '--untracked-files=all', '--', DIR)
const authSchema = () => readFileSync(join(root, AUTH_SCHEMA), 'utf8')

if (base) checkHistory(base)
if (!historyOnly) {
  const kit = ['--filter', '@saas-foundation/db', 'exec', 'drizzle-kit']
  run('drizzle-kit check (migration history)', 'pnpm', [...kit, 'check'])
  const migrationsBefore = porcelain()
  if (run('drizzle-kit generate', 'pnpm', [...kit, 'generate']) && porcelain() !== migrationsBefore)
    errors.push(
      `the schema has changes without a migration; drizzle-kit generate wrote:\n${porcelain()}review and commit them (pnpm db:generate)`,
    )
  const authBefore = authSchema()
  if (run('pnpm auth:generate', 'pnpm', ['auth:generate']) && authSchema() !== authBefore)
    errors.push(
      `${AUTH_SCHEMA} is out of date with Better Auth; it was regenerated: review it, then pnpm db:generate`,
    )
}

for (const e of errors) console.error(`check-migrations: ${e}`)
process.exit(errors.length ? 1 : 0)
